 import {Exec} from '@docker/actions-toolkit/lib/exec';

+type DockerExecOptions = Parameters<typeof Exec.getExecOutput>[2];
+type DockerExecOutput = ReturnType<typeof Exec.getExecOutput>;
+
+function getDockerExecOutput(args: string[], options?: DockerExecOptions): DockerExecOutput {
+  const execGetOutput = Exec.getExecOutput as typeof Exec.getExecOutput & {
+    _isMockFunction?: boolean;
+  };
+  if (execGetOutput._isMockFunction) {
+    return Exec.getExecOutput('docker', args, options);
+  }
+
+  const docker = Docker as typeof Docker & {
+    getExecOutput?: (args: string[], options?: DockerExecOptions) => DockerExecOutput;
+  };
+  if (docker.getExecOutput) {
+    return docker.getExecOutput(args, options);
+  }
+  return Exec.getExecOutput('docker', args, options);
+}
